referenceSolutions.javascript:
function bookingRackFloorTicket(drawers, k) {
  const a=drawers; let out=[];
  const rows=a.map(r=>[...r]).sort((x,y)=>x[1]-y[1]||x[0]-y[0]);let end=-Infinity;for(const [s,e]of rows)if(s>=end){out.push(e-s);end=e;}
  return out.length?Math.min(...out):0;
}

